INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('0e263689-a8c7-4789-a86d-5267d3e9f977', 'destinations-roumanie-itineraire-7-jours', 'day_5_detail', 'textarea', 'Viscri est ce qui reste de la Roumanie d''avant. Un village saxon où les rues sont en terre battue, où les charrettes croisent les vélos, où le seul bruit vient des cloches des moutons. L''église fortifiée classée UNESCO domine le village. La Fondation Charles (le prince Charles a une maison ici) a aidé à restaurer plusieurs bâtiments, mais l''esprit reste celui d''un village qui vit pour lui-même, pas pour les touristes. On déjeune chez Elena, dans sa cour, assis sur un banc en bois. On repart en comprenant pourquoi on voyage vraiment.', NULL, 'Jour 5 — détail', NULL, true, '2026-08-01T13:04:34.708586+00:00', '2026-08-19T00:41:02.192672+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
