INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('14ce00dd-1dad-4b2b-9aeb-85d2f86175e6', 'destinations-roumanie-itineraire-10-jours', 'day_10_detail', 'textarea', 'Dernière gorgée de Maramureș. On prend le temps d''un dernier petit déjeuner — pain chaud, crème fraîche, confiture maison. On achète du miel et de la palincă. Puis la route vers Cluj, 2h30 de virages à travers les collines. Dans l''avion, on est fatigués mais comblés. Dix jours qui ont tout donné. Et déjà, on sait qu''on reviendra — il reste tant de Roumanie à découvrir.', NULL, 'Jour 10 — détail', NULL, true, '2026-08-01T13:04:34.708586+00:00', '2026-08-19T00:41:02.192672+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
