INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('2665df65-0729-4ffa-b397-3df487706430', 'destinations-roumanie-itineraire-10-jours', 'day_9_detail', 'textarea', 'Le Maramureș se vit, pas se visite. On commence au marché de Sighetu Marmației — le dimanche matin, c''est l''effervescence. Paysans en costume traditionnel, fromages de brebis affinés sous l''écorce, pains cuits au feu de bois. L''après-midi, on enchaîne les églises en bois classées UNESCO : Bârsana, Ieud, Desești — chacune avec sa flèche qui perce le ciel. Le soir, le dîner chez l''habitant est un moment suspendu. C''est pour ça qu''on voyage jusqu''ici.', NULL, 'Jour 9 — détail', NULL, true, '2026-08-01T13:04:34.708586+00:00', '2026-08-19T00:41:02.192672+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
