INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('482d5de7-1377-4769-a960-213c0465398a', 'destinations-roumanie-timisoara', 'intro_2__ancienne_coquille', 'textarea', 'Timișoara est roumaine, mais elle parle hongrois, serbe et allemand dans la même phrase. C''est une ville de carrefour, d''influences mêlées, d''histoire dense. Et depuis 2023, capitale européenne de la culture qui a investi dans ses scènes alternatives sans perdre son âme de quartier.', NULL, 'Introduction 2', NULL, false, '2026-08-01T13:04:34.612954+00:00', '2026-08-19T08:44:46.789017+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
