INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('703f07ea-f58f-4f3d-80cf-d3ff92464921', 'destinations-roumanie-itineraire-7-jours', 'day_6_detail', 'textarea', 'Cluj, c''est l''autre Roumanie. Étudiante, connectée, tournée vers l''avenir. Le contraste avec Viscri est brutal : on passe du silence absolu aux terrasses bondées de l''avenue Eroilor. La vie culturelle est bouillonnante — théâtre alternatif, galeries d''art contemporain, bars qui ferment à 4h du matin. On flâne dans le quartier Mărăști, on boit un café chez Laika, on dîne dans un bistro hongrois. Cluj est un rappel que la Roumanie ne se réduit pas à ses cartes postales médiévales.', NULL, 'Jour 6 — détail', NULL, true, '2026-08-01T13:04:34.708586+00:00', '2026-08-19T00:41:02.192672+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
