INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('7dbb7287-cad8-4d8e-ada5-1747ee4c052f', 'destinations-roumanie-itineraire-7-jours', 'day_7_detail', 'textarea', 'Dernier matin à Cluj. On traîne au marché Piața Unirii, on achète un dernier cozonac (brioche à la noix), on boit un café à Laika en faisant le bilan. Sept jours qui passent trop vite — c''est toujours le signe d''un bon voyage. Le vol retour depuis Cluj est direct vers plusieurs villes européennes. Dans l''avion, on commence déjà à rêver au prochain retour. Parce qu''on reviendra — la Roumanie a cette capacité à retenir ceux qui prennent le temps de la connaître.', NULL, 'Jour 7 — détail', NULL, true, '2026-08-01T13:04:34.708586+00:00', '2026-08-19T00:41:02.192672+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
