INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('9f3859c7-3d7f-4425-a7bd-7092fcad872b', 'destinations-sardaigne', 'intro_1', 'textarea', 'La Sardaigne, c''est l''île qui reste. Pas dans le sens d''un souvenir vague — dans le sens d''un endroit qui s''installe et ne repart plus. Les plages du sud autour de Cagliari, les lagunes roses aux flamants, les dunes sauvages de Piscinas. Et puis l''intérieur : les villages de pierre, les fêtes bariolées, les pecorino vieux qu''on mange au couteau.', NULL, 'Introduction 1', NULL, true, '2026-08-01T13:04:34.612954+00:00', '2026-08-19T00:40:54.186093+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('9f6d392a-6dd0-4dcd-8157-e2b646b1aa7b', 'destinations-portugal', 'faq_2_a', 'textarea', 'Vols directs depuis Paris vers Lisbonne (2h30), Porto (2h15) ou Funchal/Madère (3h30). EasyJet, Ryanair et TAP proposent des liaisons régulières. En train via Madrid est possible mais long (environ 20h).', NULL, 'FAQ 2 — réponse', NULL, true, '2026-08-01T13:04:34.612954+00:00', '2026-08-19T00:40:58.334867+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
