INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('aee52309-0959-4647-940a-c97b158bf874', 'destinations-roumanie-itineraire-5-jours', 'day_3_detail', 'textarea', 'Sighișoara est un arrêt obligé, et on comprend pourquoi dès qu''on franchit la tour de l''Horloge. La citadelle est vivante, habitée, pas un décor pour touristes. On flâne dans les ruelles pavées, on monte les marches couvertes jusqu''au sommet, et le soir venu, on s''installe au din Turn pour un dîner qui restera dans les mémoires.', NULL, 'Jour 3 — détail', NULL, true, '2026-08-01T13:04:34.708586+00:00', '2026-08-19T00:41:02.192672+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
