INSERT INTO public.cms_editable_zones ("id", "page", "zone_key", "zone_type", "value", "default_val", "label", "description", "is_active", "created_at", "updated_at") VALUES ('d101ab95-e856-4aae-8571-964eea9e85ce', 'destinations-roumanie-itineraire-7-jours', 'blurb', 'html', 'On a testé cet itinéraire en septembre 2024, en plein automne doré. Les températures étaient douces (18-25°C), les couleurs incroyables et les sites nettement moins fréquentés qu''en juillet-août. Chaque étape a été vérifiée, chaque adresse testée — on ne recommande que ce qu''on a vraiment expérimenté. <strong>Budget réel : 1 150 € pour deux, tout compris.</strong>', NULL, 'Blurb « Testé par Heldonica »', NULL, true, '2026-08-01T13:04:34.708586+00:00', '2026-08-19T00:41:02.192672+00:00') ON CONFLICT ("id") DO UPDATE SET "page" = EXCLUDED."page", "zone_key" = EXCLUDED."zone_key", "zone_type" = EXCLUDED."zone_type", "value" = EXCLUDED."value", "default_val" = EXCLUDED."default_val", "label" = EXCLUDED."label", "description" = EXCLUDED."description", "is_active" = EXCLUDED."is_active", "created_at" = EXCLUDED."created_at", "updated_at" = EXCLUDED."updated_at";
